{
  "root": "main_stack",
  "state": {
    "weekly_modules": [
      {
        "week": "Week 1",
        "description": "Present Subjunctive: Focus on opinion and emotion clauses. Reading: 2h, Writing: 3h, Oral: 3h, Listening: 2h."
      },
      {
        "week": "Week 2",
        "description": "Past Subjunctive: Master 'Imperfecto de Subjuntivo' in hypothetical scenarios. Focus on Reading Comprehension Task 1."
      },
      {
        "week": "Week 3",
        "description": "Conditional Sentences: Si + Imperfect Subjunctive + Conditional structure. Focus on Listening Comprehension Task 2."
      },
      {
        "week": "Week 4",
        "description": "Connectors & Cohesion: Master formal transition words for Written Expression. Saturday: Full Mock Exam 1."
      },
      {
        "week": "Week 5",
        "description": "Argumentation: Expressing pros/cons for Oral Expression Task 1. Focus on complex vocabulary for social issues."
      },
      {
        "week": "Week 6",
        "description": "Passive Voice & Se: Focus on formal writing styles. Saturday: Full Mock Exam 2."
      },
      {
        "week": "Week 7",
        "description": "Specific Vocab: Environment, technology, and health. Review of all grammar weak points."
      },
      {
        "week": "Week 8",
        "description": "Final Polish: High-intensity exam simulation and timing strategy."
      }
    ],
    "final_tasks": [
      {
        "task": "Task 1",
        "description": "Complete 3 full-length past Reading papers under strict 70-minute timers."
      },
      {
        "task": "Task 2",
        "description": "Record yourself for 5 minutes presenting a 'social debate' topic and review for filler words."
      },
      {
        "task": "Task 3",
        "description": "Write 2 formal letters of complaint/request (Written Task 1) and self-check against the DELE rubric."
      },
      {
        "task": "Task 4",
        "description": "Listen to 5 'Radio Nacional de España' news segments and summarize the main arguments in writing."
      },
      {
        "task": "Task 5",
        "description": "Review your 'Error Log' of every mistake made in the previous 7 weeks."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "header_card",
        "weekly_modules_section",
        "final_tasks_section",
        "quick_actions_section"
      ]
    },
    "header_card": {
      "type": "Card",
      "props": {},
      "children": [
        "header_content_stack"
      ]
    },
    "header_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "title_with_image",
        "prep_details_stack"
      ]
    },
    "title_with_image": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "header_image",
        "header_icon",
        "main_title"
      ]
    },
    "header_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Flag_of_Spain.svg/1200px-Flag_of_Spain.svg.png",
        "width": 40,
        "height": 40
      },
      "children": []
    },
    "header_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/mortarboard.svg"
      },
      "children": []
    },
    "main_title": {
      "type": "Text",
      "props": {
        "text": "DELE B2 Spanish: 8-Week Prep",
        "variant": "h1"
      },
      "children": []
    },
    "prep_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "prep_detail_start_end",
        "prep_detail_level",
        "prep_detail_commitment"
      ]
    },
    "prep_detail_start_end": {
      "type": "Text",
      "props": {
        "text": "Start Date: Sept 01, 2024 | End Date: Oct 27, 2024",
        "variant": "body"
      },
      "children": []
    },
    "prep_detail_level": {
      "type": "Text",
      "props": {
        "text": "Level: Intermediate (B1 → B2)",
        "variant": "body"
      },
      "children": []
    },
    "prep_detail_commitment": {
      "type": "Text",
      "props": {
        "text": "Commitment: 10 Hours/Week",
        "variant": "body"
      },
      "children": []
    },
    "weekly_modules_section": {
      "type": "Card",
      "props": {},
      "children": [
        "weekly_modules_header",
        "weekly_modules_table"
      ]
    },
    "weekly_modules_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "weekly_modules_icon",
        "weekly_modules_title"
      ]
    },
    "weekly_modules_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/calendar.svg"
      },
      "children": []
    },
    "weekly_modules_title": {
      "type": "Text",
      "props": {
        "text": "Weekly Study Modules",
        "variant": "h2"
      },
      "children": []
    },
    "weekly_modules_table": {
      "type": "Table",
      "props": {
        "statePath": "/weekly_modules",
        "columns": [
          {
            "key": "week",
            "label": "Week"
          },
          {
            "key": "description",
            "label": "Module Focus"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "week",
        "highlightColumns": [
          "description"
        ]
      },
      "children": []
    },
    "final_tasks_section": {
      "type": "Card",
      "props": {},
      "children": [
        "final_tasks_header",
        "final_tasks_table"
      ]
    },
    "final_tasks_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "final_tasks_icon",
        "final_tasks_title"
      ]
    },
    "final_tasks_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/check-circle.svg"
      },
      "children": []
    },
    "final_tasks_title": {
      "type": "Text",
      "props": {
        "text": "Final Preparation Tasks",
        "variant": "h2"
      },
      "children": []
    },
    "final_tasks_table": {
      "type": "Table",
      "props": {
        "statePath": "/final_tasks",
        "columns": [
          {
            "key": "task",
            "label": "Task"
          },
          {
            "key": "description",
            "label": "Description"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "task",
        "highlightColumns": [
          "description"
        ]
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Card",
      "props": {},
      "children": [
        "quick_actions_header",
        "quick_actions_buttons_stack"
      ]
    },
    "quick_actions_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "quick_actions_icon",
        "quick_actions_title"
      ]
    },
    "quick_actions_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/lightning.svg"
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "button_enroll",
        "button_contact"
      ]
    },
    "button_enroll": {
      "type": "Button",
      "props": {
        "label": "Enroll Now",
        "variant": "primary"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/enroll"
          }
        }
      },
      "children": []
    },
    "button_contact": {
      "type": "Button",
      "props": {
        "label": "Contact Instructor"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/contact"
          }
        }
      },
      "children": []
    }
  }
}
